def data_uri(role):
    svg = STICKERS.get(role)
    if not svg:
        return ""
    return "data:image/svg+xml;base64," + base64.b64encode(svg.encode("utf8")).decode("ascii")


def all_uris():
    return {r: data_uri(r) for r in STICKERS}


def css():
    """頁面 CSS：.av 是頭貼的共同樣式，.av-ma 等是各角色的圖。只需在頁面放一次。"""
    rules = [".av{display:inline-block;flex:none;width:44px;height:44px;border-radius:50%;background-size:cover;"
             "background-position:center;vertical-align:middle}"]
    for role, cls in CLASS.items():
        rules.append(f'.av-{cls}{{background-image:url("{data_uri(role)}")}}')
    return "".join(rules)


def av(role, extra=""):
    """一個頭貼的 HTML。找不到角色時回傳空字串。"""
    cls = CLASS.get(role)
    return f'<span class="av av-{cls}"{(" " + extra) if extra else ""}></span>' if cls else ""
